customCSS:
.t, .history { color: #808080; }
.join { color: #6a9955; }
.part, .quit { color: #808080; }
.kick, .error { color: #f44747; }
.notice { color: #dcdcaa; }
.action { color: #c586c0; }
.mode, .nick, .topic, .server { color: #4ec9b0; }
.highlight { color: #d4d4d4; background-color: #264f78; border-left: 3px solid #c586c0; padding-left: 8px; }
.reply { color: #808080; border-left: 2px solid #569cd6; padding-left: 6px; }
.oper { color: #1e1e1e; background-color: #dcdcaa; }
.reactions { color: #569cd6; background-color: #252526; }
.card { background-color: #252526; border-color: #808080; }
.card-title { color: #569cd6; }
.card-desc { color: #808080; }
.daychange { color: #808080; border-color: #252526; }
